export function calculatePartitionCount(
  peakMbPerSec: number,
  producerMbPerSec = 30,
  consumerMbPerSec = 5,
  brokerCount = 6
): number {
  const neededForProducers = Math.ceil(peakMbPerSec / producerMbPerSec);
  const neededForConsumers = Math.ceil(peakMbPerSec / consumerMbPerSec);
  const rawPartitions = Math.max(neededForProducers, neededForConsumers);

  // Round up to nearest multiple of broker count for even distribution
  const balancedPartitions = Math.ceil(rawPartitions / brokerCount) * brokerCount;
  return Math.max(balancedPartitions, brokerCount);
}

// Example: 100 MB/sec throughput with 5 MB/sec consumer rate on 6 brokers
// Returns: 24 Partitions (4 partitions per broker)
